    [ObservableProperty] private MenuItemVm? _selectedMenuItem;

    /// <summary>菜单是否展开（true=展开，false=折叠），供 ToggleSwitch 和 NavMenu 模板共用</summary>
    [ObservableProperty] private bool _isMenuExpanded = true;
    
    public MainViewModel()
    {
        // 初始化日期（只算一次）
        CurrentDate = DateTime.Now.ToString("yyyy-MM-dd");

        // 初始化时间
        CurrentTime = DateTime.Now.ToString("HH:mm:ss");

        // 每秒刷新时间
        _timer = new DispatcherTimer
        {
            Interval = TimeSpan.FromSeconds(1)
        };
        _timer.Tick += (_, _) =>
        {
            CurrentTime = DateTime.Now.ToString("HH:mm:ss");

            // 如果应用跨天运行，日期也要跟着变
            var today = DateTime.Now.ToString("yyyy-MM-dd");
            if (CurrentDate != today)
                CurrentDate = today;
        };
        _timer.Start();
        // ===== 启动默认页面：Embedded（临时调试）=====
        SelectedMenuItem = MenuItems[3];
    }
    
