    [ObservableProperty]
    private object? _currentPage;
    
    private readonly Dictionary<string, ViewModelBase> _pageCache = new();
    
    partial void OnSelectedMenuItemChanged(MenuItemVm? value)
    {
        if (value?.Name is not string name)
        {
            Console.WriteLine($"SelectedMenuItemChanged: name为空");
            return;
        }
        Console.WriteLine($"准备加载页面：{name}");

        if (!_pageCache.TryGetValue(name, out var vm))
        {
            Console.WriteLine($"【缓存未命中】新建ViewModel {name}");
            vm = name switch
            {
                "Home" => new HomeViewModel(),
                "PLC" => new PLCViewModel(),
                "DataBase" => new DataBaseViewModel(),
                "Embedded" => new EmbeddedViewModel(),
                "OS" => new OSViewModel(),
                "RealTime" => new RealTimeViewModel(),
                _ => null
            };
            if (vm != null)
                _pageCache[name] = vm;
        }
        else
        {
            Console.WriteLine($"【缓存命中】直接复用 {name}");
        }

        CurrentPage = vm;
    }
    
}


public class MenuItemVm
{
    public string Header { get; set; }
    public string Name { get; set; }
    
    public object Icon { get; set; }  // 或 ICommand
    public bool IsSeparator { get; set; }
}